+import java.util.AbstractQueue;
+import java.util.Arrays;
+import java.util.ConcurrentModificationException;
+import java.util.Iterator;
+import java.util.NoSuchElementException;
+import java.util.Objects;
+
+public final class CircularQueue<T> extends AbstractQueue<T> {
+
+    private static final String EMPTY_QUEUE_MESSAGE = "Queue is empty.";
+    private static final String FULL_QUEUE_MESSAGE = "Queue is full.";
+
+    private final Object[] elements;
+    private int head;
+    private int tail;
+    private int size;
+    private int modificationCount;
+
+    public CircularQueue(int capacity) {
+        if (capacity <= 0) {
+            throw new IllegalArgumentException("Capacity must be positive.");
+        }
+
+        this.elements = new Object[capacity];
+        this.head = 0;
+        this.tail = 0;
+        this.size = 0;
+        this.modificationCount = 0;
+    }
+
+    public void enqueue(T value) {
+        if (!offer(value)) {
+            throw new IllegalStateException(FULL_QUEUE_MESSAGE);
+        }
+    }
+
+    public T dequeue() {
+        requireNotEmpty();
+        T value = removeHead();
+        modificationCount++;
+        return value;
+    }
+
+    public T peekFront() {
+        requireNotEmpty();
+        return elementAt(head);
+    }
+
+    public T peekRear() {
+        requireNotEmpty();
+        return elementAt(indexFromHead(size - 1));
+    }
+
+    public T getFront() {
+        return peekFront();
+    }
+
+    public T getRear() {
+        return peekRear();
+    }
+
+    @Override
+    public boolean isEmpty() {
+        return size == 0;
+    }
+
+    public boolean isFull() {
+        return size == elements.length;
+    }
+
+    @Override
+    public boolean offer(T value) {
+        Objects.requireNonNull(value, "Queue elements must be non-null.");
+        if (isFull()) {
+            return false;
+        }
+
+        insertAtTail(value);
+        modificationCount++;
+        return true;
+    }
+
+    @Override
+    public T poll() {
+        if (isEmpty()) {
+            return null;
+        }
+
+        T value = removeHead();
+        modificationCount++;
+        return value;
+    }
+
+    @Override
+    public T peek() {
+        if (isEmpty()) {
+            return null;
+        }
+        return elementAt(head);
+    }
+
+    @Override
+    public int size() {
+        return size;
+    }
+
+    public int capacity() {
+        return elements.length;
+    }
+
+    public int remainingCapacity() {
+        return capacity() - size;
+    }
+
+    @Override
+    public void clear() {
+        Arrays.fill(elements, null);
+        head = 0;
+        tail = 0;
+        size = 0;
+        modificationCount++;
+    }
+
+    @Override
+    public Iterator<T> iterator() {
+        return new QueueIterator();
+    }
+
+    @Override
+    public String toString() {
+        StringBuilder builder = new StringBuilder("[");
+        for (int i = 0; i < size; i++) {
+            if (i > 0) {
+                builder.append(", ");
+            }
+            builder.append(elementAt(indexFromHead(i)));
+        }
+        return builder.append(']').toString();
+    }
+
+    private int advance(int index) {
+        return (index + 1) % elements.length;
+    }
+
+    private int indexFromHead(int offset) {
+        return (head + offset) % elements.length;
+    }
+
+    private void requireNotEmpty() {
+        if (isEmpty()) {
+            throw new IllegalStateException(EMPTY_QUEUE_MESSAGE);
+        }
+    }
+
+    private void insertAtTail(T value) {
+        elements[tail] = value;
+        tail = advance(tail);
+        size++;
+    }
+
+    @SuppressWarnings("unchecked")
+    private T removeHead() {
+        T value = elementAt(head);
+        elements[head] = null;
+        head = advance(head);
+        size--;
+        return value;
+    }
+
+    @SuppressWarnings("unchecked")
+    private T elementAt(int index) {
+        return (T) elements[index];
+    }
+
+    private final class QueueIterator implements Iterator<T> {
+
+        private final int expectedModificationCount = modificationCount;
+        private int offset;
+
+        @Override
+        public boolean hasNext() {
+            ensureUnmodified();
+            return offset < size;
+        }
+
+        @Override
+        public T next() {
+            ensureUnmodified();
+            if (!hasNext()) {
+                throw new NoSuchElementException();
+            }
+
+            T value = elementAt(indexFromHead(offset));
+            offset++;
+            return value;
+        }
+
+        private void ensureUnmodified() {
+            if (expectedModificationCount != modificationCount) {
+                throw new ConcurrentModificationException();
+            }
+        }
+    }
+}
+
+class myQueue {
+
+    private final CircularQueue<Integer> queue;
+
+    public myQueue(int cap) {
+        this.queue = new CircularQueue<>(cap);
+    }
+
+    public void enqueue(int value) {
+        queue.offer(value);
