+        assertThrows(IllegalStateException.class, () -> queue.enqueue(9), "enqueue should throw when the queue is full");
+        assertEquals(Integer.valueOf(0), Integer.valueOf(queue.remainingCapacity()), "remaining capacity should be zero when full");
+    }
