+        assertEquals(Integer.valueOf(2), Integer.valueOf(queue.dequeue()), "legacy wrapper should continue dequeuing in FIFO order");
+        assertEquals(Integer.valueOf(-1), Integer.valueOf(queue.dequeue()), "legacy wrapper should return sentinel when empty");
+    }
